/// How an image is sampled when it is not drawn at its own size.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Sampling {
    /// `auto`: bilinear for magnification, exact area for minification.
    Auto,
    /// `pixelated`: nearest texel.
    Pixelated,
    /// `crisp-edges`: nearest texel.
    CrispEdges,
}

impl Wire for Sampling {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Auto => {
                0u32.encode(w);
            }
            Self::Pixelated => {
                1u32.encode(w);
            }
            Self::CrispEdges => {
                2u32.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::Auto),
            1 => Ok(Self::Pixelated),
            2 => Ok(Self::CrispEdges),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => Ok(()),
            1 => Ok(()),
            2 => Ok(()),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = 4;
    const MAX_LEN: usize = 4;
}

#[cfg(test)]
impl crate::sample::Sample for Sampling {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        match g.below(3) {
            0 => Self::Auto,
            1 => Self::Pixelated,
            _ => Self::CrispEdges,
        }
    }
}

/// One drawing operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Item {
    /// Fill a path with one colour.
    FillPath {
        /// The path.
        path: Path,
        /// Its colour.
        colour: Colour,
    },
    /// Draw part of an image into a rectangle.
    DrawImage {
        /// Which image.
        image: ImageRef,
        /// The source rectangle, in texels.
        source: Rect,
        /// The destination rectangle, in device pixels.
        dest: Rect,
        /// How to sample it.
        sampling: Sampling,
    },
    /// Begin an isolated group, to be composited when it is popped.
    PushGroup {
        /// How the group composites into what is below it.
        blend: BlendMode,
        /// The group's opacity, 0 to 255.
        opacity: u8,
    },
    /// End the innermost group and composite it.
    PopGroup,
}

impl Wire for Item {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::FillPath { path, colour } => {
                0u32.encode(w);
                path.encode(w);
                colour.encode(w);
            }
            Self::DrawImage {
                image,
                source,
                dest,
                sampling,
            } => {
                1u32.encode(w);
                image.encode(w);
                source.encode(w);
                dest.encode(w);
                sampling.encode(w);
            }
            Self::PushGroup { blend, opacity } => {
                2u32.encode(w);
                blend.encode(w);
                opacity.encode(w);
            }
            Self::PopGroup => {
                3u32.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::FillPath {
                path: Wire::decode(r)?,
                colour: Wire::decode(r)?,
            }),
            1 => Ok(Self::DrawImage {
                image: Wire::decode(r)?,
                source: Wire::decode(r)?,
                dest: Wire::decode(r)?,
                sampling: Wire::decode(r)?,
            }),
            2 => Ok(Self::PushGroup {
                blend: Wire::decode(r)?,
                opacity: Wire::decode(r)?,
            }),
            3 => Ok(Self::PopGroup),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => {
                <Path as Wire>::validate(r)?;
                <Colour as Wire>::validate(r)?;
                Ok(())
            }
            1 => {
                <ImageRef as Wire>::validate(r)?;
                <Rect as Wire>::validate(r)?;
                <Rect as Wire>::validate(r)?;
                <Sampling as Wire>::validate(r)?;
                Ok(())
            }
            2 => {
                <BlendMode as Wire>::validate(r)?;
                <u8 as Wire>::validate(r)?;
                Ok(())
            }
            3 => Ok(()),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_min(
                hg_ipc::wire::len_min(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(0, <Path as Wire>::MIN_LEN),
                        <Colour as Wire>::MIN_LEN,
                    ),
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(
                                hg_ipc::wire::len_add(0, <ImageRef as Wire>::MIN_LEN),
                                <Rect as Wire>::MIN_LEN,
                            ),
                            <Rect as Wire>::MIN_LEN,
                        ),
                        <Sampling as Wire>::MIN_LEN,
                    ),
                ),
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <BlendMode as Wire>::MIN_LEN),
                    <u8 as Wire>::MIN_LEN,
                ),
            ),
            0,
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_max(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(0, <Path as Wire>::MAX_LEN),
                        <Colour as Wire>::MAX_LEN,
                    ),
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(
                                hg_ipc::wire::len_add(0, <ImageRef as Wire>::MAX_LEN),
                                <Rect as Wire>::MAX_LEN,
                            ),
                            <Rect as Wire>::MAX_LEN,
                        ),
                        <Sampling as Wire>::MAX_LEN,
                    ),
                ),
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <BlendMode as Wire>::MAX_LEN),
                    <u8 as Wire>::MAX_LEN,
                ),
            ),
            0,
        ),
    );
}

#[cfg(test)]
impl crate::sample::Sample for Item {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        use crate::sample::Sample;
        match g.below(4) {
            0 => Self::FillPath {
                path: Sample::sample(g),
                colour: Sample::sample(g),
            },
            1 => Self::DrawImage {
                image: Sample::sample(g),
                source: Sample::sample(g),
                dest: Sample::sample(g),
                sampling: Sample::sample(g),
            },
            2 => Self::PushGroup {
                blend: Sample::sample(g),
                opacity: Sample::sample(g),
            },
            _ => Self::PopGroup,
        }
    }
}

/// One chunk of a display list.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Chunk {
    /// The layer origin, in whole device pixels, that every path's
    /// coordinates are relative to. Held in two i32 because the IDL
    /// has no i64 pair type and the two halves are read together.
    pub origin_x: i64,
    /// The layer origin's y.
    pub origin_y: i64,
    /// Its items, at most 4,096 (graphics 6.3).
    pub items: hg_ipc::BoundedVec<Item, 4096>,
}

impl Wire for Chunk {
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(0, <i64 as Wire>::MIN_LEN),
            <i64 as Wire>::MIN_LEN,
        ),
        <hg_ipc::BoundedVec<Item, 4096> as Wire>::MIN_LEN,
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(0, <i64 as Wire>::MAX_LEN),
            <i64 as Wire>::MAX_LEN,
        ),
        <hg_ipc::BoundedVec<Item, 4096> as Wire>::MAX_LEN,
    );
    fn encode(&self, w: &mut Writer) {
        self.origin_x.encode(w);
        self.origin_y.encode(w);
        self.items.encode(w);
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        Ok(Self {
            origin_x: Wire::decode(r)?,
            origin_y: Wire::decode(r)?,
            items: Wire::decode(r)?,
        })
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <i64 as Wire>::validate(r)?;
        <i64 as Wire>::validate(r)?;
        <hg_ipc::BoundedVec<Item, 4096> as Wire>::validate(r)?;
        Ok(())
    }
}

#[cfg(test)]
impl crate::sample::Sample for Chunk {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        use crate::sample::Sample;
        Self {
            origin_x: Sample::sample(g),
            origin_y: Sample::sample(g),
            items: Sample::sample(g),
        }
    }
}
